53	    authenticate(deps.wsAuth, request)
54	      .then(user => {
55	        if (!user) {
56	          rejectSocket(socket, '401 Unauthorized');
57	          return;
58	        }
59	
60	        wss.handleUpgrade(request, socket, head, ws => {
61	          const extWs = ws as ExtWebSocket;
62	          extWs.userId = user.id;
63	          extWs.workspaceId = user['workspaceId'] as string | number | undefined;
